module sequence_detector(
    input clk, 
    input reset_n, 
    input data_in,
    output sequence_detected
);
// Internal state declaration
reg [3:0] current_state, next_state;
// Define state parameters
parameter IDLE = 4'b0000;
parameter S1 = 4'b0001;
parameter S2 = 4'b0010;
parameter S3 = 4'b0011;
parameter S4 = 4'b0100;
// Sequential logic block
always @(posedge clk or posedge reset_n) begin
    if (reset_n) begin
        current_state <= IDLE;
    end else begin
        current_state <= next_state;
    end
end
// Combinational logic block
always @(*) begin
    case(current_state)
        IDLE: begin
            if(data_in == 1'b1) begin
                next_state = S1;
            end else begin
                next_state = IDLE;
            end
        end

        S1: begin
            if(data_in == 1'b0) begin
                next_state = S2;
            end else begin
                next_state = S1;
            end
        end

        S2: begin
            if(data_in == 1'b0) begin
                next_state = S3;
            end else begin
                next_state = S1;
            end
        end

        S3: begin
            if(data_in == 1'b1) begin
                next_state = S4;
            end else begin
                next_state = IDLE;
            end
        end

        default: begin
            next_state = IDLE;
        end
    endcase
end
// Output logic
assign sequence_detected = (current_state == S4);
endmodule
